    {'technology': 'mysql', 'topic': 'joins', 'name': 'Inner Join Two Tables', 'slug': 'inner-join-two-tables', 'description': "A customers table has columns id and name, and an orders table has columns id, customer_id, and amount. Write a query that returns each customer's name alongside each of their order amounts, ordered by customer id then order id. Customers with no orders should not appear.", 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': 'Print each customer name and order amount pair.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,2,20);", 'output': 'Ana|50\nBen|20'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Inner join customers and orders on customer_id, ordered by customer id then order id\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,2,20);", 'Ana|50\nBen|20\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,10),(2,1,15),(3,2,5);", 'Cy|10\nCy|15\nDee|5\n', True, 1)], 'reference_query': 'SELECT customers.name, orders.amount FROM customers JOIN orders ON orders.customer_id = customers.id ORDER BY customers.id, orders.id;'},
    {'technology': 'mysql', 'topic': 'joins', 'name': 'Left Join With Unmatched Rows', 'slug': 'left-join-with-unmatched-rows', 'description': "A customers table has columns id and name, and an orders table has columns id, customer_id, and amount. Write a query that returns every customer's name and their order amount, using a LEFT JOIN so customers with no orders still appear with a NULL amount. Order by customer id.", 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': 'Print each customer name and order amount, including customers with no orders.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50);", 'output': 'Ana|50\nBen|'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Left join customers and orders on customer_id, ordered by customer id\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50);", 'Ana|50\nBen|\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee'),(3,'Eli');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,2,5);", 'Cy|\nDee|5\nEli|\n', True, 1)], 'reference_query': 'SELECT customers.name, orders.amount FROM customers LEFT JOIN orders ON orders.customer_id = customers.id ORDER BY customers.id;'},
    {'technology': 'mysql', 'topic': 'joins', 'name': 'Join and Filter', 'slug': 'join-and-filter', 'description': 'A customers table has columns id and name, and an orders table has columns id, customer_id, and amount. Write a query that returns the name of every customer who has an order with amount greater than 20, with no duplicate names, ordered alphabetically.', 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': 'Print the name of each qualifying customer.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,1,5),(3,2,10);", 'output': 'Ana'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- Join customers and orders, filter amount > 20, distinct names, ordered alphabetically\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,1,5),(3,2,10);", 'Ana\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,100),(2,2,1);", 'Cy\n', True, 1)], 'reference_query': 'SELECT DISTINCT customers.name FROM customers JOIN orders ON orders.customer_id = customers.id WHERE orders.amount > 20 ORDER BY customers.name;'},
    {'technology': 'mysql', 'topic': 'joins', 'name': 'Join and Aggregate', 'slug': 'join-and-aggregate', 'description': "A customers table has columns id and name, and an orders table has columns id, customer_id, and amount. Write a query that returns each customer's name and the number of orders they have placed, including customers with zero orders, ordered by customer id.", 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': "Print each customer's name and order count.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,1,20);", 'output': 'Ana|2\nBen|0'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': '-- Left join customers and orders, group by customer, count orders, ordered by customer id\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50),(2,1,20);", 'Ana|2\nBen|0\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee'),(3,'Eli');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,3,5);", 'Cy|0\nDee|0\nEli|1\n', True, 1)], 'reference_query': 'SELECT customers.name, COUNT(orders.id) FROM customers LEFT JOIN orders ON orders.customer_id = customers.id GROUP BY customers.id ORDER BY customers.id;'},
    {'technology': 'mysql', 'topic': 'joins', 'name': 'Self Join', 'slug': 'self-join', 'description': "A staff table has columns id, name, and manager_id (the id of another row in the same table, or NULL for no manager). Write a query that returns each employee's name alongside their manager's name, using a self join. Only include employees who have a manager, ordered by employee id.", 'input_format': 'There is no input; the staff table already exists with sample data.', 'output_format': "Print each employee's name and their manager's name.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE staff(id INTEGER, name TEXT, manager_id INTEGER);\nINSERT INTO staff VALUES (1,'Ana',NULL),(2,'Ben',1),(3,'Cy',1);", 'output': 'Ben|Ana\nCy|Ana'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Self join staff to itself on manager_id, ordered by employee id\n', 'tests': [("CREATE TABLE staff(id INTEGER, name TEXT, manager_id INTEGER);\nINSERT INTO staff VALUES (1,'Ana',NULL),(2,'Ben',1),(3,'Cy',1);", 'Ben|Ana\nCy|Ana\n', False, 1), ("CREATE TABLE staff(id INTEGER, name TEXT, manager_id INTEGER);\nINSERT INTO staff VALUES (1,'Dee',NULL),(2,'Eli',1);", 'Eli|Dee\n', True, 1)], 'reference_query': 'SELECT e.name, m.name FROM staff e JOIN staff m ON e.manager_id = m.id ORDER BY e.id;'},
    {'technology': 'mysql', 'topic': 'subqueries', 'name': 'Subquery in WHERE', 'slug': 'subquery-in-where', 'description': 'A students table has columns id, name, and score. Write a query that returns the name of every student whose score is above the average score, ordered by id.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print the name of each above-average student.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',40),(3,'Cy',50);", 'output': 'Ana'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Select name where score > (SELECT AVG(score) FROM students), ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',40),(3,'Cy',50);", 'Ana\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',10),(2,'Eli',90),(3,'Fay',20);", 'Eli\n', True, 1)], 'reference_query': 'SELECT name FROM students WHERE score > (SELECT AVG(score) FROM students) ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'subqueries', 'name': 'Subquery With IN', 'slug': 'subquery-with-in', 'description': 'A customers table has columns id and name, and an orders table has columns id, customer_id, and amount. Write a query that returns the name of every customer who has at least one order, using IN with a subquery, ordered alphabetically.', 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': 'Print the name of each customer who has ordered.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50);", 'output': 'Ana'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Select name where id IN (SELECT customer_id FROM orders), ordered by name\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50);", 'Ana\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee'),(3,'Eli');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,3,5),(2,2,1);", 'Dee\nEli\n', True, 1)], 'reference_query': 'SELECT name FROM customers WHERE id IN (SELECT customer_id FROM orders) ORDER BY name;'},
    {'technology': 'mysql', 'topic': 'subqueries', 'name': 'Correlated Subquery', 'slug': 'correlated-subquery', 'description': 'An employees table has columns id, name, department, and salary. Write a query that returns the name of every employee whose salary equals the maximum salary within their own department, ordered by id.', 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print the name of each top earner in their department.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',100),(2,'Ben','IT',50),(3,'Cy','HR',70);", 'output': 'Ana\nCy'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- Select name where salary equals the max salary in the same department (correlated subquery)\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',100),(2,'Ben','IT',50),(3,'Cy','HR',70);", 'Ana\nCy\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',10),(2,'Eli','Ops',10),(3,'Fay','IT',5);", 'Dee\nEli\nFay\n', True, 1)], 'reference_query': 'SELECT e.name FROM employees e WHERE e.salary = (SELECT MAX(e2.salary) FROM employees e2 WHERE e2.department = e.department) ORDER BY e.id;'},
    {'technology': 'mysql', 'topic': 'subqueries', 'name': 'Subquery in FROM', 'slug': 'subquery-in-from', 'description': "An employees table has columns id, name, department, and salary. Write a query that computes each department's total salary in a derived table (a subquery in FROM), then returns departments whose total exceeds 100, ordered by department.", 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print each qualifying department and its total.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',80),(2,'Ben','IT',80),(3,'Cy','HR',50);", 'output': 'IT|160'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': '-- Compute per-department totals in a subquery, then filter total > 100, ordered by department\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',80),(2,'Ben','IT',80),(3,'Cy','HR',50);", 'IT|160\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',200),(2,'Eli','IT',10);", 'Ops|200\n', True, 1)], 'reference_query': 'SELECT department, total FROM (SELECT department, SUM(salary) AS total FROM employees GROUP BY department) AS totals WHERE total > 100 ORDER BY department;'},
    {'technology': 'mysql', 'topic': 'subqueries', 'name': 'Subquery With NOT IN', 'slug': 'subquery-with-not-in', 'description': 'A customers table has columns id and name, and an orders table has columns id, customer_id, and amount. Write a query that returns the name of every customer who has never placed an order, using NOT IN with a subquery, ordered alphabetically.', 'input_format': 'There is no input; the customers and orders tables already exist with sample data.', 'output_format': 'Print the name of each customer with no orders.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50);", 'output': 'Ben'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Select name where id NOT IN (SELECT customer_id FROM orders), ordered by name\n', 'tests': [("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Ana'),(2,'Ben');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,1,50);", 'Ben\n', False, 1), ("CREATE TABLE customers(id INTEGER, name TEXT);\nINSERT INTO customers VALUES (1,'Cy'),(2,'Dee'),(3,'Eli');\nCREATE TABLE orders(id INTEGER, customer_id INTEGER, amount INTEGER);\nINSERT INTO orders VALUES (1,3,5);", 'Cy\nDee\n', True, 1)], 'reference_query': 'SELECT name FROM customers WHERE id NOT IN (SELECT customer_id FROM orders) ORDER BY name;'},
    {'technology': 'mysql', 'topic': 'common-table-expressions', 'name': 'A Basic CTE', 'slug': 'a-basic-cte', 'description': 'A students table has columns id, name, and score. Write a query using a WITH clause (a CTE) that selects all students, then select the name and score from that CTE, ordered by id.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "Print each row's name and score.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'output': 'Ana|82\nBen|59'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- WITH all_students AS (SELECT * FROM students) SELECT name, score ... ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',59);", 'Ana|82\nBen|59\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Cy',91),(2,'Dee',40),(3,'Eli',65);", 'Cy|91\nDee|40\nEli|65\n', True, 1)], 'reference_query': 'WITH all_students AS (SELECT * FROM students) SELECT name, score FROM all_students ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'common-table-expressions', 'name': 'A CTE With Aggregation', 'slug': 'a-cte-with-aggregation', 'description': "An employees table has columns id, name, department, and salary. Write a query using a CTE that computes each department's total salary, then selects department and total from the CTE where the total exceeds 100, ordered by department.", 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print each qualifying department and its total salary.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',80),(2,'Ben','IT',80),(3,'Cy','HR',50);", 'output': 'IT|160'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- WITH totals AS (per-department SUM(salary)) SELECT ... WHERE total > 100, ordered by department\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',80),(2,'Ben','IT',80),(3,'Cy','HR',50);", 'IT|160\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',200),(2,'Eli','IT',10);", 'Ops|200\n', True, 1)], 'reference_query': 'WITH totals AS (SELECT department, SUM(salary) AS total FROM employees GROUP BY department) SELECT department, total FROM totals WHERE total > 100 ORDER BY department;'},
    {'technology': 'mysql', 'topic': 'common-table-expressions', 'name': 'Filtering Through a CTE', 'slug': 'filtering-through-a-cte', 'description': 'A students table has columns id, name, and score. Write a query using a CTE that selects all students, then, from that CTE, selects the names of students scoring 60 or above, ordered by id.', 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': 'Print the name of each qualifying student.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',40),(3,'Cy',70);", 'output': 'Ana\nCy'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- WITH all_students AS (SELECT * FROM students) SELECT name WHERE score >= 60, ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',90),(2,'Ben',40),(3,'Cy',70);", 'Ana\nCy\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',10),(2,'Eli',99),(3,'Fay',61);", 'Eli\nFay\n', True, 1)], 'reference_query': 'WITH all_students AS (SELECT * FROM students) SELECT name FROM all_students WHERE score >= 60 ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'common-table-expressions', 'name': 'Multiple CTEs', 'slug': 'multiple-ctes', 'description': 'An employees table has columns id, name, department, and salary. Write a query that defines two CTEs: high_earners (employees with salary above 100) and their count per department, named counts. Select department and count from counts, ordered by department.', 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': 'Print each department and its count of high earners.', 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',150),(2,'Ben','IT',50),(3,'Cy','HR',200);", 'output': 'HR|1\nIT|1'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': '-- WITH high_earners AS (...), counts AS (...) SELECT department, count ... ordered by department\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',150),(2,'Ben','IT',50),(3,'Cy','HR',200);", 'HR|1\nIT|1\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',300),(2,'Eli','Ops',400),(3,'Fay','IT',10);", 'Ops|2\n', True, 1)], 'reference_query': 'WITH high_earners AS (SELECT * FROM employees WHERE salary > 100), counts AS (SELECT department, COUNT(*) AS count FROM high_earners GROUP BY department) SELECT department, count FROM counts ORDER BY department;'},
    {'technology': 'mysql', 'topic': 'common-table-expressions', 'name': 'A Recursive CTE', 'slug': 'a-recursive-cte', 'description': 'Write a query using a recursive CTE that generates the integers from 1 through 5, one per row, in increasing order. Start the recursive term at 1 and stop once the value would exceed 5.', 'input_format': 'There is no input for this problem.', 'output_format': 'Print the integers 1 through 5, one per line.', 'constraints': 'None.', 'examples': [{'input': '', 'output': '1\n2\n3\n4\n5'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- WITH RECURSIVE counter(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM counter WHERE n < 5) SELECT n FROM counter;\n', 'tests': [('', '1\n2\n3\n4\n5\n', False, 1)], 'reference_query': 'WITH RECURSIVE counter(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM counter WHERE n < 5) SELECT n FROM counter;'},
    {'technology': 'mysql', 'topic': 'window-functions', 'name': 'Row Number Over All Rows', 'slug': 'row-number-over-all-rows', 'description': "A students table has columns id, name, and score. Write a query that returns each student's name and a row number assigned in descending order of score (1 = highest score).", 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "Print each row's name and its rank position by score.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',91),(3,'Cy',40);", 'output': 'Ben|1\nAna|2\nCy|3'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 1, 'starter': '-- Select name, ROW_NUMBER() OVER (ORDER BY score DESC)\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',82),(2,'Ben',91),(3,'Cy',40);", 'Ben|1\nAna|2\nCy|3\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',10),(2,'Eli',99),(3,'Fay',50);", 'Eli|1\nFay|2\nDee|3\n', True, 1)], 'reference_query': 'SELECT name, ROW_NUMBER() OVER (ORDER BY score DESC) FROM students;'},
    {'technology': 'mysql', 'topic': 'window-functions', 'name': 'Rank Within a Partition', 'slug': 'rank-within-a-partition', 'description': "An employees table has columns id, name, department, and salary. Write a query that returns each employee's name, department, and their salary rank within their own department (1 = highest paid in that department), ordered by department then rank.", 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': "Print each row's name, department, and rank.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',100),(2,'Ben','IT',200),(3,'Cy','HR',50);", 'output': 'Cy|HR|1\nBen|IT|1\nAna|IT|2'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 2, 'starter': '-- Select name, department, RANK() OVER (PARTITION BY department ORDER BY salary DESC), ordered by department, rank\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',100),(2,'Ben','IT',200),(3,'Cy','HR',50);", 'Cy|HR|1\nBen|IT|1\nAna|IT|2\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',10),(2,'Eli','Ops',90),(3,'Fay','IT',5);", 'Fay|IT|1\nEli|Ops|1\nDee|Ops|2\n', True, 1)], 'reference_query': 'SELECT name, department, RANK() OVER (PARTITION BY department ORDER BY salary DESC) AS r FROM employees ORDER BY department, r;'},
    {'technology': 'mysql', 'topic': 'window-functions', 'name': 'A Running Total', 'slug': 'a-running-total', 'description': "A students table has columns id, name, and score. Write a query that returns each student's name and a running total of score, accumulated in id order.", 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "Print each row's name and the running total of score up to that row.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',10),(2,'Ben',20),(3,'Cy',5);", 'output': 'Ana|10\nBen|30\nCy|35'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 3, 'starter': '-- Select name, SUM(score) OVER (ORDER BY id), ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',10),(2,'Ben',20),(3,'Cy',5);", 'Ana|10\nBen|30\nCy|35\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',1),(2,'Eli',2),(3,'Fay',3),(4,'Gus',4);", 'Dee|1\nEli|3\nFay|6\nGus|10\n', True, 1)], 'reference_query': 'SELECT name, SUM(score) OVER (ORDER BY id) FROM students ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'window-functions', 'name': 'Average Within a Partition', 'slug': 'average-within-a-partition', 'description': "An employees table has columns id, name, department, and salary. Write a query that returns each employee's name, department, and their department's average salary (rounded to 2 decimals), computed with a window function, ordered by id.", 'input_format': 'There is no input; the employees table already exists with sample data.', 'output_format': "Print each row's name, department, and the department average salary.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',100),(2,'Ben','IT',300),(3,'Cy','HR',50);", 'output': 'Ana|IT|200.0\nBen|IT|200.0\nCy|HR|50.0'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 4, 'starter': '-- Select name, department, ROUND(AVG(salary) OVER (PARTITION BY department),2), ordered by id\n', 'tests': [("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Ana','IT',100),(2,'Ben','IT',300),(3,'Cy','HR',50);", 'Ana|IT|200.0\nBen|IT|200.0\nCy|HR|50.0\n', False, 1), ("CREATE TABLE employees(id INTEGER, name TEXT, department TEXT, salary INTEGER);\nINSERT INTO employees VALUES (1,'Dee','Ops',10),(2,'Eli','Ops',30);", 'Dee|Ops|20.0\nEli|Ops|20.0\n', True, 1)], 'reference_query': 'SELECT name, department, ROUND(AVG(salary) OVER (PARTITION BY department), 2) FROM employees ORDER BY id;'},
    {'technology': 'mysql', 'topic': 'window-functions', 'name': "The Previous Row's Value", 'slug': 'the-previous-rows-value', 'description': "A students table has columns id, name, and score. Write a query that returns each student's name and the score of the previous row in id order, using LAG. The first row's previous score should be NULL.", 'input_format': 'There is no input; the students table already exists with sample data.', 'output_format': "Print each row's name and the previous row's score.", 'constraints': 'None.', 'examples': [{'input': "CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',10),(2,'Ben',20),(3,'Cy',30);", 'output': 'Ana|\nBen|10\nCy|20'}], 'language': 'mysql', 'language_id': 82, 'difficulty': 'Easy', 'order': 5, 'starter': '-- Select name, LAG(score) OVER (ORDER BY id), ordered by id\n', 'tests': [("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Ana',10),(2,'Ben',20),(3,'Cy',30);", 'Ana|\nBen|10\nCy|20\n', False, 1), ("CREATE TABLE students(id INTEGER, name TEXT, score INTEGER);\nINSERT INTO students VALUES (1,'Dee',5),(2,'Eli',15);", 'Dee|\nEli|5\n', True, 1)], 'reference_query': 'SELECT name, LAG(score) OVER (ORDER BY id) FROM students ORDER BY id;'},
